def solve(data):
    packages = data.get('packages', {})
    roots = data.get('roots', {})
    names = sorted(packages)
    best = None
    best_vector = None

    def search(selected, constraints):
        nonlocal best, best_vector

        for name, row in selected.items():
            if name not in constraints or not in_range(row['version'], constraints[name]):
                return

        unresolved = [name for name in constraints if name not in selected]
        if not unresolved:
            vector = tuple(selected[name]['version'] if name in selected else -1
                           for name in names)
            if best_vector is None or vector > best_vector:
                best_vector = vector
                best = {name: row['version'] for name, row in selected.items()}
            return

        name = min(unresolved)
        candidates = [row for row in packages.get(name, [])
                      if in_range(row['version'], constraints[name])]
        candidates.sort(key=lambda row: row['version'], reverse=True)
        for row in candidates:
            next_selected = dict(selected)
            next_selected[name] = row
            next_constraints = dict(constraints)
            valid = True
            for dep in row.get('deps', []):
                target, bounds = dependency(dep)
                if not target or target not in packages:
                    valid = False
                    break
                if target in next_constraints:
                    old = next_constraints[target]
                    lo = max(old[0], bounds[0])
                    hi = min(old[1], bounds[1])
                    if lo > hi:
                        valid = False
                        break
                    next_constraints[target] = (lo, hi)
                else:
                    next_constraints[target] = bounds
                if target in next_selected and not in_range(
                        next_selected[target]['version'], next_constraints[target]):
                    valid = False
                    break
            if valid:
                search(next_selected, next_constraints)

    initial = {}
    valid_roots = True
    for name, bounds in roots.items():
        if name not in packages:
            valid_roots = False
            break
        initial[name] = tuple(bounds)
    if valid_roots:
        search({}, initial)

    if best is None:
        return {'error': 'unsatisfiable'}
    return {'versions': best}
